import { describe, expect, it } from 'vitest';
import { hasAiAttribution } from '../commit/no-ai-attribution.mjs';

describe('hasAiAttribution', () => {
  it.each([
    'feat: x\n\nCo-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>',
    'feat: x\n\nco-authored-by: someone <noreply@anthropic.com>',
    'feat: x\n\n🤖 Generated with [Claude Code](https://claude.com/claude-code)',
    'feat: x\n\nGenerated by Claude',
  ])('detects %j', (message) => {
    expect(hasAiAttribution(message)).toBe(true);
  });

  it.each([
    'feat: x\n\nCo-authored-by: Jane Doe <jane@example.com>',
    'docs: describe the Claude Code workflow in CLAUDE.md',
    'chore(deps): bump vitest from 5.0.3 to 5.0.4',
  ])('accepts %j', (message) => {
    expect(hasAiAttribution(message)).toBe(false);
  });

  it.each([
    ['co-authored-by:', 'co-authored-by:'.repeat(20_000)],
    ['generated by', 'generated by '.repeat(20_000)],
  ])('stays linear on adversarial input repeating %j', (_name, input) => {
    const started = performance.now();
    expect(hasAiAttribution(input)).toBe(false);
    expect(performance.now() - started).toBeLessThan(200);
  });
});
